/* Ctrl.h: register map Ctrl (soc), generated by tern. Do not edit.
 *
 * <MAP>_<REG>_OFFSET          byte offset of a register in the block
 * <MAP>_<REG>_<FIELD>_SHIFT   bit position of a field
 * <MAP>_<REG>_<FIELD>_MASK    field bits in the register word
 * <MAP>_<REG>_<FIELD>_GET(v)  field value of register word v
 * <MAP>_<REG>_<FIELD>_SET(v, x)  v with the field replaced by x
 * <map>_read_<reg>(base) / <map>_write_<reg>(base, v)  volatile accesses
 */
#ifndef CTRL_H
#define CTRL_H

#include <stdint.h>

/* ctrl: read/write, 32 bits. Engine control. */
#define CTRL_CTRL_OFFSET 0x00u
#define CTRL_CTRL_ENABLE_SHIFT 0u
#define CTRL_CTRL_ENABLE_WIDTH 1u
#define CTRL_CTRL_ENABLE_MASK 0x00000001u
#define CTRL_CTRL_ENABLE_GET(v) (((v) & CTRL_CTRL_ENABLE_MASK) >> CTRL_CTRL_ENABLE_SHIFT)
#define CTRL_CTRL_ENABLE_SET(v, x) (((v) & ~CTRL_CTRL_ENABLE_MASK) | (((uint32_t)(x) << CTRL_CTRL_ENABLE_SHIFT) & CTRL_CTRL_ENABLE_MASK))
#define CTRL_CTRL_MODE_SHIFT 1u
#define CTRL_CTRL_MODE_WIDTH 2u
#define CTRL_CTRL_MODE_MASK 0x00000006u
#define CTRL_CTRL_MODE_GET(v) (((v) & CTRL_CTRL_MODE_MASK) >> CTRL_CTRL_MODE_SHIFT)
#define CTRL_CTRL_MODE_SET(v, x) (((v) & ~CTRL_CTRL_MODE_MASK) | (((uint32_t)(x) << CTRL_CTRL_MODE_SHIFT) & CTRL_CTRL_MODE_MASK))
#define CTRL_CTRL_MODE_OFF 0u  /* Mode::Off */
#define CTRL_CTRL_MODE_SLOW 1u  /* Mode::Slow */
#define CTRL_CTRL_MODE_FAST 2u  /* Mode::Fast */
#define CTRL_CTRL_MODE_TURBO 3u  /* Mode::Turbo */
static inline uint32_t ctrl_read_ctrl(uintptr_t base)
{
    return *(volatile const uint32_t *)(base + CTRL_CTRL_OFFSET);
}
static inline void ctrl_write_ctrl(uintptr_t base, uint32_t v)
{
    *(volatile uint32_t *)(base + CTRL_CTRL_OFFSET) = v;
}

/* status: read-only, 32 bits */
#define CTRL_STATUS_OFFSET 0x04u
#define CTRL_STATUS_BUSY_SHIFT 0u
#define CTRL_STATUS_BUSY_WIDTH 1u
#define CTRL_STATUS_BUSY_MASK 0x00000001u
#define CTRL_STATUS_BUSY_GET(v) (((v) & CTRL_STATUS_BUSY_MASK) >> CTRL_STATUS_BUSY_SHIFT)
#define CTRL_STATUS_BUSY_SET(v, x) (((v) & ~CTRL_STATUS_BUSY_MASK) | (((uint32_t)(x) << CTRL_STATUS_BUSY_SHIFT) & CTRL_STATUS_BUSY_MASK))
#define CTRL_STATUS_ERR_SHIFT 1u
#define CTRL_STATUS_ERR_WIDTH 1u
#define CTRL_STATUS_ERR_MASK 0x00000002u
#define CTRL_STATUS_ERR_GET(v) (((v) & CTRL_STATUS_ERR_MASK) >> CTRL_STATUS_ERR_SHIFT)
#define CTRL_STATUS_ERR_SET(v, x) (((v) & ~CTRL_STATUS_ERR_MASK) | (((uint32_t)(x) << CTRL_STATUS_ERR_SHIFT) & CTRL_STATUS_ERR_MASK))
static inline uint32_t ctrl_read_status(uintptr_t base)
{
    return *(volatile const uint32_t *)(base + CTRL_STATUS_OFFSET);
}

/* count: read/write, 32 bits. Bytes processed <since reset> & so on. */
#define CTRL_COUNT_OFFSET 0x08u
static inline uint32_t ctrl_read_count(uintptr_t base)
{
    return *(volatile const uint32_t *)(base + CTRL_COUNT_OFFSET);
}
static inline void ctrl_write_count(uintptr_t base, uint32_t v)
{
    *(volatile uint32_t *)(base + CTRL_COUNT_OFFSET) = v;
}

/* fifo: write-only, 8 bits, FIFO: each write pushes */
#define CTRL_FIFO_OFFSET 0x10u
static inline void ctrl_write_fifo(uintptr_t base, uint8_t v)
{
    *(volatile uint8_t *)(base + CTRL_FIFO_OFFSET) = v;
}

/* irq: read, write 1 to clear, 32 bits */
#define CTRL_IRQ_OFFSET 0x14u
#define CTRL_IRQ_DONE_SHIFT 0u
#define CTRL_IRQ_DONE_WIDTH 1u
#define CTRL_IRQ_DONE_MASK 0x00000001u
#define CTRL_IRQ_DONE_GET(v) (((v) & CTRL_IRQ_DONE_MASK) >> CTRL_IRQ_DONE_SHIFT)
#define CTRL_IRQ_DONE_SET(v, x) (((v) & ~CTRL_IRQ_DONE_MASK) | (((uint32_t)(x) << CTRL_IRQ_DONE_SHIFT) & CTRL_IRQ_DONE_MASK))
#define CTRL_IRQ_OVERFLOW_SHIFT 1u
#define CTRL_IRQ_OVERFLOW_WIDTH 1u
#define CTRL_IRQ_OVERFLOW_MASK 0x00000002u
#define CTRL_IRQ_OVERFLOW_GET(v) (((v) & CTRL_IRQ_OVERFLOW_MASK) >> CTRL_IRQ_OVERFLOW_SHIFT)
#define CTRL_IRQ_OVERFLOW_SET(v, x) (((v) & ~CTRL_IRQ_OVERFLOW_MASK) | (((uint32_t)(x) << CTRL_IRQ_OVERFLOW_SHIFT) & CTRL_IRQ_OVERFLOW_MASK))
static inline uint32_t ctrl_read_irq(uintptr_t base)
{
    return *(volatile const uint32_t *)(base + CTRL_IRQ_OFFSET);
}
static inline void ctrl_write_irq(uintptr_t base, uint32_t v)
{
    *(volatile uint32_t *)(base + CTRL_IRQ_OFFSET) = v;
}

/* irq_set: read, write 1 to set, 32 bits */
#define CTRL_IRQ_SET_OFFSET 0x18u
static inline uint32_t ctrl_read_irq_set(uintptr_t base)
{
    return *(volatile const uint32_t *)(base + CTRL_IRQ_SET_OFFSET);
}
static inline void ctrl_write_irq_set(uintptr_t base, uint32_t v)
{
    *(volatile uint32_t *)(base + CTRL_IRQ_SET_OFFSET) = v;
}

#endif /* CTRL_H */
